{async (me) => {
   	var data = await me.callGetFromURL('/api/quan-tri/nguoi-dung?filter=%7B%22tai_khoan%22%3A%'+me.record.taiKhoan+'%7D&search=&page=1&page_size=100000&sort=%22%22').then(res => {
		return res.data.data;
    })
	.catch(err => {
		return [];
	});
    if(data.filter(x=>x.id!==me.record.id && x.tai_khoan===me.record.tai_khoan).length > 0) return 'Tài khoản người dùng đã tồn tại';
	else return '';
}}

